    <!-- =========================================================
         TYPING ANIMATION
    ========================================================== -->

    <script>
        document.addEventListener(
            'DOMContentLoaded',
            function ()
            {
                const textElement =
                    document.getElementById(
                        'dashboardWelcomeText'
                    );

                const cursorElement =
                    document.getElementById(
                        'dashboardWelcomeCursor'
                    );

                if (!textElement)
                {
                    return;
                }

                const welcomeText =
                    'Welcome to SIKAP (Sistem Kelengkapan Administrasi Personil)';

                let index = 0;

                const typingSpeed = 55;

                function typeWelcome()
                {
                    if (index < welcomeText.length)
                    {
                        textElement.textContent +=
                            welcomeText.charAt(index);

                        index++;

                        window.setTimeout(
                            typeWelcome,
                            typingSpeed
                        );

                        return;
                    }

                    if (cursorElement)
                    {
                        window.setTimeout(
                            function ()
                            {
                                cursorElement.classList.add(
                                    'finished'
                                );
                            },
                            450
                        );
                    }
                }

                window.setTimeout(
                    typeWelcome,
                    250
                );
            }
        );
    </script>

